return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'पुनर्निर्माण गरिएको Page Builder Sandwich-को आधार रिलिज: सेटिङहरू र \'बारेमा\' स्क्रिन, फुटप्रिन्ट-मुक्त फ्रन्ट-एन्ड आउटपुट लेयर, र एउटा नमूना सामग्री ब्लक।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'एआई प्रदायकहरू','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT का निर्माताहरू। एक राम्रो सर्वगुण सम्पन्न।','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude का निर्माताहरू। लेखन र तार्किक विश्लेषणमा सक्षम।','Google\'s Gemini models. Fast and inexpensive.'=>'Google को Gemini मोडेलहरू। छिटो र किफायती।','A European AI company with fast, inexpensive models.'=>'द्रुत र सस्तो मोडेलहरू भएको युरोपेली AI कम्पनी।','Low-cost models that are good at writing and code.'=>'लेखन र कोडमा राम्रा र कम लागतका मोडेलहरू।','One key for models from many different providers.'=>'धेरै विभिन्न प्रदायकहरूका मोडलहरूका लागि एउटा मुख्य कुञ्जी।','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'तपाईंको आफ्नै कम्प्युटर वा सर्भरमा चलिरहेको मोडेललगायत OpenAI को API जस्तै काम गर्ने कुनै पनि सेवा।','General (used when nothing more specific is set)'=>'सामान्य (केही विशिष्ट सेट नभएको बेला प्रयोग गरिन्छ)','Writing and rewriting'=>'लेखन र पुनर्लेखन','Translation'=>'अनुवाद','Code and CSS'=>'कोड र सीएसएस','Sorry, you are not allowed to access this page.'=>'माफ गर्नुहोस्, तपाईलाई यो पृष्ठमा प्रवेश गर्ने अनुमति छैन।','These settings are shared by every plugin that uses them: %s.'=>'यी सेटिङहरू तिनीहरूलाई प्रयोग गर्ने हरेक प्लगइनद्वारा साझा गरिएका छन्: %s।','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'तपाईंका कुञ्जीहरू यस साइटको डेटाबेसमा इन्क्रिप्ट गरिएका छन् र तपाईंले छान्नुभएको प्रदायकलाई मात्र पठाइन्छ — हामीलाई कहिल्यै पनि पठाइँदैन।','Step 1 of 2: choose an AI provider'=>'चरण १ को २: एआई प्रदायक छान्नुहोस्','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'तपाईं आफ्नो कुञ्जी आफैं ल्याउनुहुन्छ, त्यसैले तपाईंले प्रयोग गर्नुभएको कुराको लागि प्रदायकलाई सीधै भुक्तानी गर्नुहुन्छ। निश्चित हुनुहुन्न? यी मध्ये कुनै पनि राम्रोसँग काम गर्छ; तपाईं पछि थप थप्न सक्नुहुन्छ।','Next'=>'पchari','Step 2 of 2: connect %s'=>'चरण २ को २: %s जडान गर्नुहोस्','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'/v1 मा अन्त्य हुने, तपाइँको OpenAI-ससंग संगत (compatible) सेवाको ठेगाना प्रविष्ट गर्नुहोस्। सेवाले मागेको अवस्थामा मात्र साँचो (key) आवश्यक पर्दछ।','Open %s and sign in (or create a free account).'=>'%s खोल्नुहोस् र लगइन गर्नुहोस् (वा निःशुल्क खाता सिर्जना गर्नुहोस्)।','the %s API keys page'=>'%s API कुञ्जीहरूको पृष्ठ','Create a new key and copy it.'=>'एउटा नयाँ कुञ्जी सिर्जना गर्नुहोस् र यसलाई प्रतिलिपि गर्नुहोस्।','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'यसलाई तल टाँस्नुहोस् र "Save and test" मा थिच्नुहोस्। यो काम गर्छ कि गर्दैन भनेर जाँच गर्न हामी एउटा सानो अनुरोध पठाउँछौं।','Most providers need a little credit on the account before a key works: %s.'=>'धेरैजसो प्रदायकहरूलाई कुञ्जी काम गर्नुअघि खातामा थोरै क्रेडिट आवश्यक पर्छ: %s।','add credit'=>'क्रेडिट थप्नुहोस्','← Choose a different provider'=>'← एउटा फरक प्रदायक छान्नुहोस्','Address'=>'ठेगाना','Saved key ends in …%s — paste a new one to replace it'=>'सुरक्षित गरिएको कुञ्जी …%s मा समाप्त हुन्छ — यसलाई बदल्न नयाँ टाँस्नुहोस्','Key (optional)'=>'कुञ्जी (ऐच्छिक)','API key'=>'API कुञ्जी','Save and test'=>'सेभ र परीक्षण गर्नुहोस्','Providers'=>'प्रदायकहरू','Provider'=>'प्रदायक','Status'=>'स्थिति','Key'=>'कुञ्जी','Get a key'=>'एउटा कुञ्जी प्राप्त गर्नुहोस्','Test'=>'परीक्षण','Remove'=>'हटाउनुहोस्','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'नयाँ प्लगइन संस्करणद्वारा बचत गरियो: यो प्लगइन अपडेट गर्नुहोस्, वा कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'सुरक्षित गरिएको कुञ्जी अब खोल्न सकिँदैन (साइटको सुरक्षा कुञ्जीहरू परिवर्तन भएका छन्)। यसलाई फेरि प्रविष्ट गर्नुहोस्।','Not connected'=>'जडित छैन','Connected — last test passed %s'=>'जडित — अन्तिम परीक्षण उत्तीर्ण भयो %s','Last test failed: %s'=>'पछिल्लो परीक्षण असफल भयो: %s','Connected — not tested yet'=>'जडान गरिएको — अहिलेसम्म परीक्षण गरिएको छैन','Which model to use'=>'कुन मोडेल प्रयोग गर्ने','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ले त्यस कार्यका लागि हाम्रो सिफारिसलाई जनाउँछ। सूचीमा प्रदायकबाट प्रत्यक्ष रूपमा पढाइएका, तपाईंको कुञ्जीले प्रयोग गर्न सक्ने हरेक मोडेल समावेश छन्।','— Recommended for the provider —'=>'— प्रदायकका लागि सिफारिस गरिएको —','Save models'=>'मोडेलहरू सुरक्षित गर्नुहोस्','Refresh the model lists from the providers'=>'प्रदायकहरूबाट मोडेल सूचीहरू रिफ्रेस गर्नुहोस्','best quality'=>'उत्तम गुणस्तर','lowest cost'=>'सबैभन्दा कम लागत','fastest'=>'सबभन्दा छिटो','Add a model yourself'=>'आफैं मोडल थप्नुहोस्','A model came out today? Paste its exact name to use it straight away.'=>'आज एउटा नयाँ मोडेल सार्वजनिक भयो? यसलाई तुरुन्तै प्रयोग गर्न यसको ठ्याक्कै नाम टाँस्नुहोस्।','Model name'=>'मोडलको नाम','Add model'=>'मोडेल थप्नुहोस्','Recommended models list'=>'सिफारिस गरिएका मोडेलहरूको सूची','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'सिफारिस गरिएका मोडेलहरूको सूची प्रमाणित गर्न सकिएन, त्यसैले कुनै पनि सिफारिसहरू देखाइएको छैन। प्लगइन पुनः स्थापना गर्नुहोस्, वा तलका दैनिक अद्यावधिकहरू सक्षम गर्नुहोस्।','The list in use was published on %s. Each plugin update brings a fresh one.'=>'प्रयोगमा रहेको सूची %s मा प्रकाशित गरिएको थियो। प्रत्येक प्लगइन अपडेटले एउटा नयाँ सूची ल्याउँछ।','Also check Zinn Digital® once a day for an updated list.'=>'अद्यावधिक गरिएको सूचीको लागि दिनको एक पटक Zinn Digital® पनि जाँच गर्नुहोस्।','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'केवल एउटा साधारण डाउनलोड अनुरोध पठाइन्छ: कुनै कुञ्जी छैन, कुनै साइट ठेगाना छैन, तपाईंको सामग्रीको बारेमा केही छैन। सूचीमा हस्ताक्षर गरिएको हुन्छ, र हस्ताक्षर जाँचमा असफल हुने सूचीलाई बेवास्ता गरिन्छ।','Last checked %1$s: %2$s.'=>'पछिल्लो पटक जाँच गरिएको %1$s: %2$s।','Save, and check now if turned on'=>'बचत गर्नुहोस्, र यदि चालू गरिएको छ भने अहिले जाँच गर्नुहोस्','a newer list was installed'=>'एउटा नयाँ सूची स्थापना गरियो','already up to date'=>'पəhle सेनै अद्यावधिक छ','the download failed the signature check and was ignored'=>'डाउनलोडले हस्ताक्षर जाँचमा असफल भयो र यसलाई बेवास्ता गरियो','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® लाई सम्पर्क गर्न सकिएन; हालको सूची प्रयोगमा रहन्छ','turned off'=>'बन्द गरिएको','Open'=>'खोल्नुहोस्','Check their status page'=>'तिनीहरूको स्थिति पृष्ठ जाँच गर्नुहोस्','Open your billing page'=>'तपाईंको बिलिङ पृष्ठ खोल्नुहोस्','Open your API keys page'=>'तपाईंको API कुञ्जीहरूको पृष्ठ खोल्नुहोस्','Open the AI settings'=>'AI सेटिङहरू खोल्नुहोस्','Sorry, you are not allowed to do that.'=>'माफ गर्नुहोस्, तपाईँलाई यो गर्न अनुमति छैन।','Unknown provider.'=>'अज्ञात प्रदायक।','Enter the address of your service, for example http://localhost:11434/v1.'=>'आफ्नो सेवाको ठेगाना प्रविष्ट गर्नुहोस्, उदाहरणका लागि http://localhost:11434/v1।','That does not look like an API key. Copy it again, without spaces.'=>'त्यो API कुञ्जी जस्तो देखिँदैन। यसलाई खाली ठाउँ बिना फेरि प्रतिलिपि (कपी) गर्नुहोस्।','Paste your API key first.'=>'पहिले आफ्नो एपीआई कुञ्जी टाँस्नुहोस्।','Key removed.'=>'कुञ्जी हटाइयो।','Models saved.'=>'मोडलहरू सुरक्षित गरियो।','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'नमुनाको सटीक नाम प्रविष्ट गर्नुहोस्, उदाहरणका लागि प्रदायकको कागजातमा लेखिएअनुसार।','Added %s. Choose it under "Which model to use".'=>'%s थपियो। यसलाई "कुन मोडल प्रयोग गर्ने" अन्तर्गत छान्नुहोस्।','Model removed.'=>'मोडेल हटाइयो।','Daily updates are off. The list that came with the plugin is used.'=>'दैनिक अपडेटहरू बन्द छन्। प्लगइनमा आएको सूची प्रयोग गरिन्छ।','Checked: %s.'=>'जाँच गरिएको: %s।','Model lists refreshed.'=>'मोडल सूचीहरू ताजा गरिएका छन्।','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'तपाईंको AI कुञ्जी तपाईंको एउटा प्लगइनको नयाँ संस्करणद्वारा सेभ गरिएको थियो। यो प्लगइन अपडेट गर्नुहोस्, वा AI सेटिङहरूमा कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'तपाईंको सुरक्षित गरिएको AI कुञ्जी अब खोल्न सकिँदैन (साइटका सुरक्षा कुञ्जीहरू परिवर्तन भएका छन्)। AI सेटिङहरूमा यसलाई फेरि प्रविष्ट गर्नुहोस्।','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI अहिलेसम्म सेट अप गरिएको छैन। AI सेटिङहरूमा AI प्रदायकको लागि कुञ्जी थप्नुहोस्।','No model is chosen for this task. Pick one in the AI settings.'=>'यस कार्यका लागि कुनै पनि मोडेल छनौट गरिएको छैन। AI सेटिङहरूमा गएर एउटा छनौट गर्नुहोस्।','That AI provider is not supported by this version of the plugin.'=>'त्यो AI प्रदायक प्लगइनको यो संस्करणद्वारा समर्थित छैन।','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'यो साइट तपाईंको AI सेवामा पुग्न सकेन। यो चालु छ कि छैन र यसको ठेगाना तपाईंको वेब सर्भरबाट पहुँचयोग्य छ कि छैन भनी जाँच गर्नुहोस् (तपाईंको आफ्नै कम्प्युटरमा रहेको सेवा होस्ट गरिएको साइटबाट पहुँचयोग्य हुँदैन)।','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'यो साइट %s सम्म पुग्न सकेन। तिनीहरूको स्थिति पृष्ठ जाँच गर्नुहोस्; यदि तिनीहरू सक्रिय छन् भने, तपाईंको होस्टले बाहिर जाने जडानहरू अवरुद्ध गरिरहेको हुन सक्छ, वा ठेगाना गलत छ।','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s ले भन्छ कि तपाईंको खातामा कुनै क्रेडिट वा कोटा बाँकी छैन। तिनीहरूसँगको आफ्नो खातामा क्रेडिट थप्नुहोस् या सीमा बढाउनुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ले तपाइँको कुञ्जी स्वीकार गरेन। यो गलत टाइप गरिएको, खारेज गरिएको वा म्याद समाप्त भएको हुन सक्छ। नयाँ कुञ्जी सिर्जना गर्नुहोस् र यसलाई यहाँ टाँस्नुहोस्।','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ले तपाईंको कुञ्जीका लागि यो अनुरोध अस्वीकार गर्‍यो। कुञ्जीसँग यो मोडल वा सुविधामा पहुँच नभएको हुन सक्छ, वा तपाईंको खाता प्रमाणित गर्नुपर्ने हुन सक्छ।','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'तपाईंको कुञ्जीका लागि %2$s बाट "%1$s" मोडल उपलब्ध छैन। AI सेटिङहरूमा अर्को मोडल छान्नुहोस्।','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'तपाईंको %2$s योजनामा ​​"%1$s" मोडल समावेश छैन। AI सेटिङहरूमा अर्को मोडल छान्नुहोस्, वा उनीहरूसँग आफ्नो योजना अपग्रेड गर्नुहोस्।','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ले तपाइँको कुञ्जीले अनुरोधहरू पठाउने गति सीमित गर्दैछ। एक मिनेट पर्खनुहोस् र फेरि प्रयास गर्नुहोस्, वा उनीहरूसँग आफ्नो दर सीमा बढाउनुहोस्।','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s मा अहिले समस्या भइरहेको छ (उनीहरूकोतर्फबाट सेवा अवरुद्ध वा अत्यधिक भार)। तपाईंको सेटिङमा कुनै समस्या छैन। केही समयपछि फेरि प्रयास गर्नुहोस्।','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'हामीले पहिचान गर्न नसकेको कारणले AI अनुरोध असफल भयो। फेरि प्रयास गर्नुहोस्; यदि यो भइरह्यो भने, तलका विवरणहरूसँगै समर्थन टोलीलाई सम्पर्क गर्नुहोस्।','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI प्रदायकले यो प्लगइनले पढ्न नसक्ने रूपमा उत्तर दियो। फेरि प्रयास गर्नुहोस्; यदि यो भइरह्यो भने, अर्को मोडेल छान्नुहोस् वा सहयोग टोलीलाई सम्पर्क गर्नुहोस्।','Custom (OpenAI-compatible)'=>'कस्टम (OpenAI-compatible)','Save a key for this provider first.'=>'पहिले यो प्रदायकका लागि कुञ्जी सुरक्षित गर्नुहोस्।','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'तपाईंको कुञ्जीले काम गर्छ, तर प्रदायकले यसको लागि कुनै पाठ मोडेल सूचीबद्ध गरेको छैन। तल आफैं एउटा मोडेल थप्नुहोस्।','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'जडान भयो। %1$s ले %2$s प्रयोग गरेर उत्तर दिनुभयो। तपाईं का AI सुविधाहरू प्रयोग गर्न तयार छन्।','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'तपाईंको प्रयोगकर्ता भूमिकालाई यो साइटमा एआई प्रयोग गर्ने अनुमति छैन। एक प्रशासकलाई सोध्नुहोस्।','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'यो साइटले यसको मासिक AI खर्च सीमा पुगेको छ। एक प्रशासकले AI सेटिङहरूमा यसलाई बढाउन सक्छन्।','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'यो साइटले AI अनुरोधहरूको मासिक सीमा पुगेको छ। एक प्रशासकले AI सेटिङहरूमा यसलाई बढाउन सक्छन्।','Usage and cost'=>'प्रयोग र लागत','The log, limits and role permissions apply to AI used through: %s.'=>'लग, सीमाहरू र भूमिका अनुमतिहरू %s मार्फत प्रयोग हुने AI मा लागू हुन्छन्।','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'लागतहरू अनुमानित हुन्, प्रकाशित मूल्यहरूबाट निकालिएको; कुनै ज्ञात मूल्य नभएको मोडेललाई शून्य मानिन्छ।','This month: %1$s requests, about %2$s.'=>'यस महिना: %1$s अनुरोधहरू, लगभग %2$s।','When'=>'कहिले','Who'=>'कसले','Used for'=>'प्रयोग गरिएको','Model'=>'मोडेल','Tokens in / out'=>'टोकन इन / आउट','About'=>'बारेमा','Result'=>'परिणाम','No AI requests have been made yet.'=>'अहिलेसम्म कुनै पनि AI अनुरोधहरू गरिएका छैनन्।','Done'=>'सम्पन्न भयो','Limits and permissions'=>'सीमाहरू र अनुमतिहरू','Monthly spending limit (US dollars)'=>'मासिक खर्च सीमा (US डलर)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'कुनै सीमा नराख्न खाली छोड्नुहोस्। अनुमानित लागत त्यहाँ पुगेktan पछि AI ले बाँकी महिनाको लागि काम रोक्छ।','Monthly request limit'=>'मासिक अनुरोध सीमा','Leave empty for no limit.'=>'कुनै सीमा नराख्न खाली छोड्नुहोस्।','Who may use AI'=>'AI कसले प्रयोग गर्न सक्छ','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'कुनै पनि नछान्नुहोस् जसले गर्दा प्लगइनका सुविधाहरू प्रयोग गर्न सक्ने सबैले AI प्रयोग गर्न सकून्। प्रशासकहरूले यसलाई सधैँ प्रयोग गर्न सक्छन्।','Save limits and permissions'=>'सीमा र अनुमतिहरू सुरक्षित गर्नुहोस्','Limits and permissions saved.'=>'सीमा र अनुमतिहरू सुरक्षित गरियो।','Security error, please refresh the page and try again.'=>'सुरक्षा त्रुटि, कृपया पृष्ठलाई रिफ्रेस गरेर फेरि प्रयास गर्नुहोस्।','Missing newsletter settings. Please contact the admin.'=>'न्यूजलेटर सेटिंग्सहरू हराइरहेको छ। कृपया प्रशासकलाई सम्पर्क गर्नुहोस्।','Invalid newsletter settings. Please contact the admin.'=>'अमान्य न्यूजलेटर सेटिङहरू। कृपया प्रशासकलाई सम्पर्क गर्नुहोस्।','Invalid email address.'=>'अमान्य इमेल ठेगाना।','Too many attempts. Please try again in a few minutes.'=>'धेरै प्रयासहरू भए। कृपया केही मिनेट पछि फेरि प्रयास गर्नुहोस्।','Something went wrong. Please contact the admin.'=>'केही गडबडी भयो। कृपया प्रशासकलाई सम्पर्क गर्नुहोस्।','Map'=>'म्याप गर्नुहोस्','Background video'=>'पृष्ठभूमि भिडियो','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: %2$d फन्ट फाइलहरू भण्डार गरिएका छन्, स्टाइलसिट %3$s','That family is not stored.'=>'त्यो परिवार भण्डारण गरिएको छैन।','Removed.'=>'हटाइयो।','That is not a valid font family name.'=>'त्यो एउटा मान्य फन्ट फेमिलीको नाम होइन।','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts ले त्यो फेमिली फर्काएन। नाम जाँच गर्नुहोस् र फेरि प्रयास गर्नुहोस्।','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'फन्ट फाइलहरू डाउनलोड गर्न वा सेभ गर्न सकिएन। uploads फोल्डरमा लेख्न मिल्ने (writable) छ कि छैन भनी जाँच गर्नुहोस्।','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'फन्ट स्टाइलसिट सेभ गर्न सकिएन। अपलोड्स फोल्डरमा लेख्न मिल्छ भनी जाँच गर्नुहोस्।','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'plugin को यो प्रतिलिपिमा admin screen का script हरू हराएका छन्। यसलाई रिलिज गरिएको प्याकेजबाट पुन: स्थापना गर्नुहोस्।','This screen needs JavaScript.'=>'यो स्क्रिनलाई जाभास्क्रिप्ट आवश्यक छ।','Languages'=>'भाषाहरू','Upgrade'=>'स्तरवृद्धि गर्नुहोस्','Pricing'=>'मूल्य निर्धारण','Start Trial'=>'परीक्षण सुरु गर्नुहोस्','Account'=>'खाता','Contact Us'=>'हामीलाई सम्पर्क गर्नुहोस्','Affiliation'=>'आबद्धता','the kind of softwarePlugin'=>'प्लगइन','greetingHey %s,'=>'नमस्ते %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'सुरक्षा र फिचर अपडेटहरू, शैक्षिक सामग्री, र समय-समयका अफरहरूको लागि इमेल सूचनाहरू प्राप्त गर्न, र केही आधारभूत WordPress वातावरण जानकारी साझेदारी गर्न अप्ट इन गर्नुहोस्। यसले हामीलाई %s लाई तपाईंको साइटसँग थप उपयुक्त बनाउन र तपाईंलाई आवश्यक पर्ने कामहरू गर्नमा अझ राम्रो बनाउन मद्दत गर्नेछ।','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'सुरक्षा र फिचर अपडेटहरू, शैक्षिक सामग्रीहरू, र समय-समयका प्रस्तावहरूको लागि इमेल सूचनाहरू प्राप्त गर्न तथा आधारभूत WordPress वातावरण जानकारी साझेदारी गर्न अप्ट इन गर्नुहोस्।','If you skip this, that\'s okay! %1$s will still work just fine.'=>'तपाईंले यो छोड्नुभयो भने पनि केही हुँदैन! %1$s ले त्यसपछि पनि राम्ररी काम गर्नेछ।','Allow & Continue'=>'अनुमति दिनुहोस् र जारी राख्नुहोस्','verbSkip'=>'छोड्नुहोस्','Skipping, please wait'=>'छोड्दै छ, कृपया प्रतीक्षा गर्नुहोस्','Continue'=>'जारी राख्नुहोस्','Please wait'=>'कृपया पर्खनुहोस्','as activating pluginActivating'=>'सक्रिय गर्दै','This will allow %s to'=>'यसले %s लाई अनुमति दिनेछ','Privacy Policy'=>'गोपनीयता नीति','Terms of Service'=>'सेवाका सर्तहरू','License Agreement'=>'लाइसेन्स सम्झौता','Have a license key?'=>'लाइसेन्स कुञ्जी छ?','Activate License'=>'लाइसेन्स सक्रिय गर्नुहोस्','View Basic Profile Info'=>'आधारभूत प्रोफाइल विवरण हेर्नुहोस्','Your WordPress user\'s: first & last name, and email address'=>'तपाईंको WordPress प्रयोगकर्ताको: पहिलो र अन्तिम नाम, र इमेल ठेगाना','View Basic Website Info'=>'आधारभूत वेबसाइट जानकारी हेर्नुहोस्','Homepage URL & title, WP & PHP versions, and site language'=>'गृहपृष्ठको URL र शीर्षक, WP र PHP संस्करणहरू, र साइटको भाषा','View Basic %s Info'=>'आधारभूत %s जानकारी हेर्नुहोस्','Current %s & SDK versions, and if active or uninstalled'=>'हालका %s र SDK संस्करणहरू, र तिनीहरू सक्रिय छन् वा अनइन्स्टल गरिएका छन्','Newsletter'=>'न्युजलेटर','Updates, announcements, marketing, no spam'=>'अपडेटहरू, घोषणाहरू, मार्केटिङ, कुनै स्पाम छैन','View Diagnostic Info'=>'डाइग्नोस्टिक जानकारी हेर्नुहोस्','WordPress & PHP versions, site language & title'=>'WordPress र PHP संस्करणहरू, साइट भाषा र शीर्षक','View Plugins & Themes List'=>'प्लगइन र थिमहरूको सूची हेर्नुहोस्','Names, slugs, versions, and if active or not'=>'नामहरू, स्लगहरू, संस्करणहरू, र सक्रिय छन् वा छैनन्','optional'=>'ऐच्छिक','Never miss an important update'=>'कुनै पनि महत्त्वपूर्ण अपडेट नछोड्नुहोस्','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'हामीले यो अप्ट-इन प्रस्तुत गरेका छौँ ताकि तपाईँले कुनै पनि महत्त्वपूर्ण अपडेट नछुटाउनुहोस् र %s लाई तपाईँको साइटसँग थप उपयुक्त बनाउन तथा तपाईँलाई आवश्यक पर्ने कार्यहरू गर्नमा अझ राम्रो बनाउन हामीलाई सहयोग गर्नुहोस्।','Thank you for updating to %1$s v%2$s!'=>'%1$s v%2$s मा अद्यावधिक गर्नुभएकोमा धन्यवाद!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'उपसर्ग १ देखि ८ वटा साना अक्षर वा अङ्कहरूको हुनुपर्छ, एउटा अक्षरबाट सुरु हुनुपर्छ, र प्लगइनको नाम हुनु हुँदैन।','You are not allowed to edit this item.'=>'तपाईंलाई यो वस्तु सम्पादन गर्ने अनुमति छैन।','You are not allowed to do this.'=>'तपाईंलाई यो गर्न अनुमति छैन।','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'तपाईंको लगइन विवरणसँग मेल नखाएका कारण सुरक्षित मोड (safe mode) बन्द गरियो। पृष्ठ पुन: लोड गर्नुहोस्।','Only an administrator can use safe mode.'=>'सुरक्षित मोड केवल एक प्रशासकले मात्र प्रयोग गर्न सक्छन्।','Safe mode needs a normal browser login.'=>'सुरक्षित मोडलाई सामान्य ब्राउजर लगइन आवश्यक पर्दछ।','Safe mode could not be set up.'=>'सुरक्षित मोड सेटअप गर्न सकिएन।','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'safe mode लाई wp-content/mu-plugins फोल्डरमा लेख्ने अनुमति (write access) आवश्यक छ।','Safe mode could not write to the wp-content/mu-plugins folder.'=>'safe mode ले wp-content/mu-plugins फोल्डरमा लेख्न सकेन।','Sandwich Studio'=>'स्यान्डविच स्टुडियो','That page does not exist, or it has been deleted.'=>'त्यो पृष्ठ अवस्थित छैन, वा यसलाई मेटाइएको छ।','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'माफ गर्नुहोस्, तपाईलाई Sandwich Studio मा यो वस्तु सम्पादन गर्ने अनुमति छैन।','Sandwich Studio is not built. Reinstall the plugin.'=>'स्यान्डविच स्टुडियो बनेको छैन। प्लगइन पुन: स्थापना गर्नुहोस्।','Add title'=>'शीर्षक थप्नुहोस्','Type / to choose a block'=>'ब्लक छनोट गर्न / टाइप गर्नुहोस्','Loading Sandwich Studio…'=>'स्यान्डविच स्टुडियो लोड हुँदैछ…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'स्यान्डविच स्टुडियोलाई जाभास्क्रिप्ट आवश्यक छ। यसको सट्टामा सामान्य सम्पादक प्रयोग गर्नुहोस्।','Edit “%s” with Sandwich Studio'=>'Sandwich Studio सँग "%s" सम्पादन गर्नुहोस्','Edit with Sandwich Studio'=>'स्यान्डविच स्टुडियोसँग सम्पादन गर्नुहोस्','Blank canvas'=>'खाली क्यानभास','A migration step is running right now. Try again in a minute.'=>'अहिले माइगेरेसन चरण चलिरहेको छ। एक मिनेटपछि फेरि प्रयास गर्नुहोस्।','Thank you for subscribing!'=>'सदस्यता लिनुभएकोमा धन्यवाद!','Something went wrong. Please contact the administrator.'=>'केही गडबडी भयो। कृपया प्रशासकलाई सम्पर्क गर्नुहोस्।','Years'=>'वर्षहरू','Months'=>'महिनाहरू','Weeks'=>'हप्ताहरू','Days'=>'दिनहरू','Hours'=>'घण्टाहरू','Minutes'=>'मिनेटहरू','Seconds'=>'सेकेन्डहरू','Go to slide %d'=>'स्लाइड %d मा जानुहोस्','You\'re already subscribed to our newsletter'=>'तपाईंले हाम्रो न्युजलेटरको सदस्यता पहिले नै लिइसकेको हुनुहुन्छ','Email address is already subscribed.'=>'इमेल ठेगाना पहिले नै सदस्यता लिइएको छ।','MailPoet plugin not found. Please contact the admin.'=>'MailPoet प्लगइन फेला परेन। कृपया प्रशासकलाई सम्पर्क गर्नुहोस्।','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Zinn Digital® Ltd का सीईओ Neil Lock द्वारा निर्मित','Version %s'=>'संस्करण %s','Page Builder Sandwich website'=>'Page Builder Sandwich वेबसाइट','Zinn Digital® website'=>'Zinn Digital® वेबसाइट','Settings saved.'=>'सेटिङहरू सेभ गरियो।','See the Pro plans and pricing'=>'प्रो योजनाहरू र मूल्यहरू हेर्नुहोस्','Front-end output'=>'front-end आउटपुट','Class name prefix'=>'क्लास नाम उपसर्ग','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'प्लगइनले तपाईंको पृष्ठहरूमा प्रिन्ट गर्ने प्रत्येक कक्षाको नाम यो उपसगबाट सुरु हुन्छ, त्यसैले पृष्ठहरूले कुन प्लगइनले तिनीहरूलाई बनायो भनेर देखाउँदैनन्। अक्षरबाट सुरु हुने, १ देखि ८ वटा साना अक्षरहरू वा अंकहरू।','Save'=>'सेभ गर्नुहोस्','Beta updates'=>'बिटा अपडेटहरू','This site receives beta versions as updates.'=>'यो साइटले बिटा संस्करणहरू अपडेटको रूपमा प्राप्त गर्दछ।','This site receives stable versions only.'=>'यो साइटले स्थिर संस्करणहरू मात्र प्राप्त गर्दछ।','Change this on the Account page'=>'यसलाई खाता पृष्ठमा परिवर्तन गर्नुहोस्','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'बिटा संस्करणहरू तिनीहरूको खातामा जोडिएका इजाजतपत्र प्राप्त प्रो स्थापनाहरूमा प्रस्ताव गरिएका छन्। एक पटक जोडिएktan पछि, तपाईंले खाता पृष्ठबाट सामेल हुन सक्नुहुन्छ।','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'यो पोस्ट रूपान्तरण गर्ने अनुरोध पूरा हुनु अघि नै रोकियो, त्यसैले पोस्ट छुटाइयो। यसलाई रूपान्तरण गर्न खोल्नुहोस्, वा यहाँबाट फेरि रूपान्तरण गर्नुहोस्।','There is no backup of this post to restore.'=>'रिस्टोर गर्न यो पोस्टको कुनै ब्याकअप छैन।','The converted content could not be saved.'=>'परिणत सामग्री सुरक्षित गर्न सकिएन।','Unknown error.'=>'अज्ञात त्रुटि।','No legacy content has been checked yet.'=>'कुनै पनि लिगेसी सामग्री अहिलेसम्म जाँच गरिएको छैन।','Restoring legacy content: %1$d of %2$d posts.'=>'पुरातन सामग्री पुनर्स्थापना गरिँदै: %1$d को %2$d पोस्टहरू।','Converting legacy content: %1$d of %2$d posts.'=>'पुरानो सामग्री रूपान्तरण गर्दै: %1$d को %2$d पोस्टहरू।','Undo finished: %1$d restored, %2$d failed.'=>'पूर्ववत कार्य सम्पन्न भयो: %1$d पुनर्स्थापना गरियो, %2$d असफल भए।','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'रूपान्तरण समाप्त भयो: %1$d रूपान्तरित, %2$d अपरिवर्तित, %3$d असफल।','Legacy content'=>'पुरानो सामग्री','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Page Builder Sandwich का अघिल्लो संस्करणहरूसँग बनाइएका पृष्ठहरू पृष्ठभूमिमा ब्लकहरूमा रूपान्तरण हुन्छन्। प्रत्येक पोस्टको पहिले नै ब्याकअप राखिन्छ, त्यसैले प्रत्येक रूपान्तरणलाई पूर्ववत (अन्डु) गर्न सकिन्छ।','%d post still holds legacy content.'=>'%d पोस्टमा अझै पनि लिगेसी सामग्री रहेको छ।' . "\0" . '%d वटा पोस्टहरूमा अझै पनि लिगेसी सामग्री छ।','%d post has a backup.'=>'%d पोस्टको ब्याकअप छ।' . "\0" . '%d वटा पोस्टहरूको ब्याकअप छ।','%d post could not be handled'=>'%d वटा पोस्ट ह्यान्डल गर्न सकिएन' . "\0" . '%d वटा पोस्टहरू ह्यान्डल गर्न सकिएन','Post %d'=>'पोष्ट %d','Conversion started. It continues in the background; you can leave this page.'=>'रूपान्तरण सुरु भयो। यो पृष्ठभूमिमा जारी रहनेछ; तपाईं यो पृष्ठ छोड्न सक्नुहुन्छ।','Convert legacy content'=>'पुरानो सामग्री रूपान्तरण गर्नुहोस्','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'प्रत्येक रूपान्तरित पोस्टलाई यसको लिगेसी सामग्रीमा पुनर्स्थापना गर्ने? रूपान्तरण भएदेखि ती पोस्टहरूमा गरिएका परिवर्तनहरू हराउनेछन्।','Undo started. It continues in the background; you can leave this page.'=>'पूर्ववत प्रक्रिया सुरु भयो। यो पृष्ठभूमिमा जारी रहनेछ; तपाईं यो पृष्ठ छोड्न सक्नुहुन्छ।','Undo all conversions'=>'सबै रूपान्तरणहरू पूर्ववत् गर्नुहोस्','Shortcode tag'=>'सर्टकट ट्याग','Use letters, numbers, dashes and underscores only.'=>'अक्षरहरू, सङ्ख्याहरू, ड्यासहरू र अन्डरस्कोरहरू मात्र प्रयोग गर्नुहोस्।','Attribute name'=>'विशेषता नाम','Add attribute'=>'विशेषता थप्नुहोस्','Content'=>'सामग्री','Shortcode'=>'सर्टकोड','Choose a shortcode tag in the block settings.'=>'ब्लक सेटिङहरूमा सर्टकोड ट्याग छान्नुहोस्।','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'पुरानो सम्पादकको "%s" नियन्त्रण ब्लक सम्पादकमा उपलब्ध छैन। मानलाई पाठको रूपमा प्रविष्ट गर्नुहोस्।','Choose image'=>'छवि छान्नुहोस्','Choose file'=>'फाइल छान्नुहोस्','— Default —'=>'— पूर्वनिर्धारित —','Advanced styling'=>'उन्नत स्टाइलिङ','Inline CSS'=>'इनलाइन सीएसएस','CSS declarations, for example: min-height: 380px; background-color: #333'=>'CSS घोषणाहरू, उदाहरणका लागि: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'प्रभावहरू (पुरानो वर्गहरू)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'पुरानो संस्करणहरूबाट सारिएका खाली ठाउँ-अलग प्रभाव नामहरू, उदाहरणका लागि: hover-shadow','Row'=>'पङ्क्ति','Width'=>'चौडाइ','Content width'=>'सामग्रीको चौडाइ','Full width'=>'पूरा चौडाइ','Full width, content kept in the middle'=>'पूर्ण चौडाइ, सामग्री बीचमा राखिएको छ','Link'=>'लिङ्क','Link address'=>'लिंक ठेगाना','Open in a new tab'=>'नयाँ ट्याबमा खोल्नुहोस्','Link relationship'=>'लिंक सम्बन्ध','Alignment'=>'पङ्क्तिबद्धता','None'=>'कुनै पनि होइन','Left'=>'बायाँ','Centre'=>'केन्द्र','Right'=>'दायाँ','Button text'=>'बटन पाठ','Add text…'=>'पाठ थप्नुहोस्…','Icon'=>'आइकन','SVG markup'=>'SVG मार्कअप','Scripts, links and external references are removed before the icon is shown.'=>'आइकन देखाउनु अघि स्क्रिप्टहरू, लिङ्कहरू र बाह्य सन्दर्भहरू हटाइन्छन्।','Accessible label'=>'पहुँचयोग्य लेबल','Leave empty for a decorative icon.'=>'सजावटी आइकनका लागि खाली छोड्नुहोस्।','Paste SVG markup in the block settings.'=>'ब्लक सेटिङहरूमा SVG मार्कअप टाँस्नुहोस्।','New setting name'=>'नयाँ सेटिङको नाम','For example: title or text'=>'उदाहरणका लागि: शीर्षक वा पाठ','Add setting'=>'सेटिङ थप्नुहोस्','Widget'=>'विजेट','Choose a widget'=>'एउटा विजेट छान्नुहोस्','Widget area'=>'विजेट क्षेत्र','Choose a widget area'=>'एउटा विजेट क्षेत्र छान्नुहोस्','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'यस छविको चौडाइ र उचाइ छैन, त्यसैले लोड हुँदा पेज हल्लिनेछ। यसलाई मिडिया लाइब्रेरीबाट छान्नुहोस्, वा यसको चौडाइ र उचाइ सेट गर्नुहोस्।','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'यो भिडियो मिडिया लाइब्ररीबाट होइन, त्यसैले यसको साइज अज्ञात छ र लोड हुँदा पेज हल्लिनेछ। यसको सट्टा यसलाई मिडिया लाइब्ररीमा अपलोड गर्नुहोस्।','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'यस HTML मा रहेको एउटा छवि, भिडियो वा फ्रेमको चौडाइ र उचाइ छैन, त्यसैले यो लोड हुँदा पृष्ठ हल्लिनेछ। यसमा चौडाइ र उचाइ विशेषताहरू थप्नुहोस्।','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'यो इम्बेड लोड भएपछि आफैँ रिसाइज हुन्छ, जसले यसको तलको सामग्रीलाई सार्छ। यसलाई ठाउँ दिनुहोस् वा पृष्ठमा तल राख्नुहोस्।','Layout shift'=>'लायआउट सिफ्ट','Heading'=>'शीर्षक','Text'=>'पाठ','Style'=>'शैली','Plain'=>'सादा','Accent'=>'उच्चारण','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'साट्नका लागि कुनै भाषाहरू छैनन्। जब अनुवाद प्लगइनले दुई वा बढी भाषाहरू सूचीबद्ध गर्छ तब स्विचर देखिन्छ।','Switcher'=>'स्वीचर','Show the current language'=>'हालको भाषा देखाउनुहोस्','%s is also editing this page. Saving may overwrite their changes.'=>'%s ले पनि यो पृष्ठ सम्पादन गरिरहनुभएको छ। बचत गर्दा उहाँका परिवर्तनहरू ओभरराइट हुन सक्छन्।','Block library'=>'ब्लक लाइब्रेरी','Layers'=>'तहहरू','Close panel'=>'प्यानल बन्द गर्नुहोस्','Page canvas'=>'पृष्ठ क्